import { memo, useEffect, useMemo, useRef, useState } from 'react';
import { Check, Copy, FileCode2 } from 'lucide-react';
import clsx from 'clsx';
import { tokenizeCpp, type Token } from './cppTokens';

interface Props {
  code: string;
  /** 1-based lines generated by the selected block(s). */
  selectedLines: ReadonlySet<number>;
  /** 1-based lines of the block the simulator is running. */
  activeLines: ReadonlySet<number>;
  /** Line → block id (clicking a mapped line focuses its block). */
  lineMap: Record<number, string>;
  onLineClick?: (line: number, blockId: string) => void;
  /** Shown in the tab above the code. */
  fileName?: string;
}

const Line = memo(function Line({ tokens }: { tokens: Token[] }) {
  if (tokens.length === 0) return <>{'​'}</>;
  return (
    <>
      {tokens.map((t, i) =>
        t.t === 'space' || t.t === 'ident' || t.t === 'punct' ? (
          <span key={i} className={t.t === 'punct' ? 'sw-tok-punct' : undefined}>
            {t.v}
          </span>
        ) : (
          <span key={i} className={`sw-tok-${t.t}`}>
            {t.v}
          </span>
        ),
      )}
    </>
  );
});

async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    try {
      const ta = document.createElement('textarea');
      ta.value = text;
      ta.style.position = 'fixed';
      ta.style.opacity = '0';
      document.body.appendChild(ta);
      ta.select();
      const ok = document.execCommand('copy');
      ta.remove();
      return ok;
    } catch {
      return false;
    }
  }
}

/** Read-only C++ viewer: line numbers, light syntax colouring, block-linked highlights, copy. */
export function CodeViewer({ code, selectedLines, activeLines, lineMap, onLineClick, fileName = 'sketch.ino' }: Props) {
  const lines = useMemo(() => tokenizeCpp(code.replace(/\n$/, '')), [code]);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [copied, setCopied] = useState<'ok' | 'fail' | null>(null);

  // Bring the first highlighted line into view when the selection changes.
  const firstSelected = useMemo(() => (selectedLines.size ? Math.min(...selectedLines) : null), [selectedLines]);
  const firstActive = useMemo(() => (activeLines.size ? Math.min(...activeLines) : null), [activeLines]);
  useEffect(() => {
    const target = firstActive ?? firstSelected;
    if (target === null) return;
    const box = scrollRef.current;
    const el = box?.querySelector<HTMLElement>(`[data-line="${target}"]`);
    if (!box || !el) return;
    const top = el.offsetTop;
    const visible = top >= box.scrollTop + 8 && top + el.offsetHeight <= box.scrollTop + box.clientHeight - 48;
    if (!visible) box.scrollTo({ top: Math.max(0, top - box.clientHeight / 3), behavior: 'smooth' });
  }, [firstSelected, firstActive]);

  useEffect(() => {
    if (!copied) return;
    const t = setTimeout(() => setCopied(null), 1600);
    return () => clearTimeout(t);
  }, [copied]);

  const gutterWidth = `${String(lines.length).length + 1}ch`;

  return (
    <div className="sw-code">
      <div className="sw-code-bar">
        <span className="sw-code-file">
          <FileCode2 size={13} />
          {fileName}
        </span>
        <span className="sw-code-meta">{lines.length === 1 ? '1 línea' : `${lines.length} líneas`}</span>
        <button
          type="button"
          className={clsx('sw-copy', copied === 'ok' && 'is-ok')}
          onClick={async () => setCopied((await copyText(code)) ? 'ok' : 'fail')}
          title="Copiar el código al portapapeles"
        >
          {copied === 'ok' ? <Check size={13} /> : <Copy size={13} />}
          <span>{copied === 'ok' ? 'Copiado' : copied === 'fail' ? 'No se pudo copiar' : 'Copiar'}</span>
        </button>
      </div>
      <div className="sw-code-scroll" ref={scrollRef} role="region" aria-label="Código Arduino generado">
        <pre className="sw-code-pre" style={{ ['--sw-gutter' as string]: gutterWidth }}>
          {lines.map((tokens, i) => {
            const n = i + 1;
            const blockId = lineMap[n];
            return (
              <div
                key={n}
                data-line={n}
                className={clsx('sw-line', selectedLines.has(n) && 'is-selected', activeLines.has(n) && 'is-active', blockId && onLineClick && 'is-linked')}
                onClick={blockId && onLineClick ? () => onLineClick(n, blockId) : undefined}
              >
                <span className="sw-ln" aria-hidden>
                  {n}
                </span>
                <code className="sw-lc">
                  <Line tokens={tokens} />
                </code>
              </div>
            );
          })}
        </pre>
      </div>
    </div>
  );
}
